import React, { useState, useEffect } from 'react';
import faqDataRaw from './data/faqData.json';
import Category from './components/Category';
import './styles.css';

function App() {
  const [categories, setCategories] = useState([]);

  useEffect(() => {
    const savedVotes = JSON.parse(localStorage.getItem('faqVotes')) || {};
    const updated = faqDataRaw.categories.map(cat => ({
      ...cat,
      questions: cat.questions.map(q => ({
        ...q,
        rating: savedVotes[q.id] ?? q.rating
      }))
    }));
    setCategories(updated);
  }, []);

  const updateRating = (catId, qId, delta) => {
    setCategories(prev =>
        prev.map(cat =>
            cat.id === catId
                ? {
                  ...cat,
                  questions: cat.questions.map(q =>
                      q.id === qId ? { ...q, rating: q.rating + delta } : q
                  )
                }
                : cat
        )
    );
  };

  useEffect(() => {
    const votes = {};
    categories.forEach(cat =>
        cat.questions.forEach(q => {
          votes[q.id] = q.rating;
        })
    );
    localStorage.setItem('faqVotes', JSON.stringify(votes));
  }, [categories]);

  const sorted = [...categories].sort((a, b) => {
    const sumA = a.questions.reduce((s, q) => s + q.rating, 0);
    const sumB = b.questions.reduce((s, q) => s + q.rating, 0);
    return sumB - sumA;
  });

  return (
      <div className="container">
        <h1>Часто задаваемые вопросы</h1>
        {sorted.map(cat => (
            <Category key={cat.id} category={cat} onVote={updateRating} />
        ))}
      </div>
  );
}

export default App;
